"""Editorial diagram data; each step specifies actual state and causal change."""


def diagram(identifier, chapter, title, intro, assumptions, nodes, edges, rows):
    data = dict(id=identifier, volume='cache', chapter=chapter, anchor=chapter,
                title=title, intro=intro, assumptions=assumptions,
                nodes=[dict(id=i, label=l, sub=s) for i, l, s in nodes],
                edges=[dict(id=i, **{'from': a, 'to': b}, label=l) for i, a, b, l in edges], steps=[])
    for title, explanation, actor, focus, active, states, name, before, after, why in rows:
        data['steps'].append(dict(title=title, explanation=explanation, actor=actor,
            focus=focus.split(), active=active.split(), states=dict(zip([n[0] for n in nodes], states)),
            fields=[dict(name=name, before=before, after=after, why=why)],
            bands=[dict(label=name, value=after, detail=why)]))
    data['takeaway'] = intro
    return data


